UPDATE products SET kit_md = replace(replace(kit_md,
'  - test — тестова подія (кнопка в адмінці).',
'  - app.insight — знахідки самоаудиту (п.1б): data.items = [{ title, why, severity: high|medium|low, area, fix }].
  - test — тестова подія (кнопка в адмінці).'),
'## 2. Якщо програма',
'## 1б. Самоаудит — програма сама шукає, що покращити
- Ловити все: помилки інтерфейсу (window.onerror, unhandledrejection, error boundary), помилки серверних функцій і фонових задач, повільні запити (>3 с), невдалі відправки форм.
- Сигнали незручності: повторні кліки по тому самому (rage-click), кинуті форми, дії, які часто скасовують, екрани, де довго нічого не відбувається, обовʼязкові поля, на яких спотикаються.
- Кнопка «Щось не працює / ідея» на кожному екрані → app.feedback (текст + сторінка + роль, без персональних даних).
- Раз на добу (вночі) — самоаудит: зібрати помилки, повільні місця і сигнали незручності за добу, віддати моделі ШІ на розбір і надіслати app.insight зі списком до 10 знахідок по важливості (що, де, чому заважає, як виправити). Без дублів знахідок, які вже надсилались і ще не виправлені.
- Все це — і в адмінці програми: «Журнал помилок» і «Що покращити» з позначкою «виправлено».

## 2. Якщо програма') WHERE name = 'Client Ops Connect';
INSERT INTO changelog (title, body, created_at) VALUES ('Програми самі кажуть, що виправити', 'Продукт → «Звʼязок»: зверху блок «Що виправити» — помилки і відгуки з програми (однакові згруповані з лічильником ×N) і знахідки самоаудиту (програма раз на добу сама шукає незручності й повільні місця і надсилає подією app.insight — вони стають ідеями продукту).
Кнопка «Промпт: виправити все це» — одне завдання для Claude Code: усі проблеми по важливості + паспорт + наприкінці витяжка-оновлення (стане «Оновленням N»). Після — «Розібрано»: наступного разу в промпт піде тільки нове.
Набір «Client Ops Connect» доповнено розділом «Самоаудит» — встав його в Claude Code програми ще раз, щоб він додав ловлю помилок, кнопку «Щось не працює» і нічний самоаудит.', datetime('now'));
